function ComprehensiveStatement()
local Res= teamyar.query(context,[[{"query":"with recursive CTE_Account AS (SELECT ID as SourceAccount,ID as AccountID, CODE AS AccountCode, PARENT , ORG_ID AS ORG_ID FROM pa_account WHERE ORG_ID = 2 UNION SELECT  CTE_Account.SourceAccount as SourceAccount,pa.ID as AccountID, pa.CODE AS AccountCode, pa.PARENT , pa.ORG_ID AS ORG_ID FROM CTE_Account INNER JOIN pa_account as pa ON CTE_Account.AccountID = pa.PARENT and CTE_Account.ORG_ID = pa.ORG_ID), cte_DateRangePerYear as (select min(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) as sdate,  max(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) edate, JYEAR FROM REPORT_DIMDATE where (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) group by JYEAR), CTE_VoucherRecords as  (select cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain from cte_DateRangePerYear inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) and pv.type in (1,4,5) and pv.status in(2,4,5,6) and pv.deleted = 0 and pvr.deleted = 0 group by cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID) ,CTE_AccountsVouchersInfo AS (select CTE_Account.SourceAccount,CTE_Account.ORG_ID,sum(CTE_VoucherRecords.remain) as remain,CTE_VoucherRecords.JYEAR from CTE_Account left join CTE_VoucherRecords on CTE_Account.AccountID=CTE_VoucherRecords.ACCOUNT_ID and CTE_Account.ORG_ID=CTE_VoucherRecords.ORG_ID group by CTE_Account.SourceAccount,CTE_Account.ORG_ID,CTE_VoucherRecords.JYEAR), CTE_OPIncomeAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2368,1648) group by ORG_ID,JYEAR), CTE_TCOPIncomeAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(1648)  group by ORG_ID,JYEAR) ,CTE_GeneralCostAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(1646)  group by ORG_ID,JYEAR), CTE_DecValCostsAccounts as(select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2053,2084,2413,2493)  group by ORG_ID,JYEAR), CTE_OtherIncAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2052)  group by ORG_ID,JYEAR), CTE_OtherCostsAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2050)  group by ORG_ID,JYEAR), CTE_FinCostsAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2104,2645)  group by ORG_ID,JYEAR), CTE_OtherNonOPAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2057)  group by ORG_ID,JYEAR ), CTE_TaxCostsAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2054,2055,2209,2489)  group by ORG_ID,JYEAR), CTE_StopOPAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 0 as type from CTE_AccountsVouchersInfo where SourceAccount in(2319)  group by ORG_ID,JYEAR), CTE_SurplusRevTangibleAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 2 as type from CTE_AccountsVouchersInfo where SourceAccount in(2605)  group by ORG_ID,JYEAR), CTE_DiffExchangeRateAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 5 as type from CTE_AccountsVouchersInfo where SourceAccount in(2304,2305,2048)  group by ORG_ID,JYEAR), cte_UnionRemainAccounts AS (SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_OPIncomeAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_TCOPIncomeAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_GeneralCostAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_DecValCostsAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_OtherIncAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_OtherCostsAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_FinCostsAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_OtherNonOPAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_TaxCostsAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_StopOPAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_SurplusRevTangibleAccounts UNION All SELECT ORG_ID, remain , JYEAR, TYPE FROM CTE_DiffExchangeRateAccounts), CTE_PureProfit as (select  ORG_ID, sum(remain) as remain, JYEAR, 1 as type from cte_UnionRemainAccounts where type= 0 group by ORG_ID, JYEAR), CTE_SurplusRevTangibleTax as (select  ORG_ID, (SUM(COALESCE(remain,0))/COALESCE(4 , 1)) * 0.09 as remain, JYEAR, 3 as type from cte_UnionRemainAccounts where type= 2 group by ORG_ID, JYEAR), CTE_SurplusRevTangibleTaxSum as (select  ORG_ID, (SUM(COALESCE(remain,0))/COALESCE(4 , 1)) + ((SUM(COALESCE(remain,0))/COALESCE(4 , 1)) * 0.09) as remain, JYEAR, 4 as type from cte_UnionRemainAccounts where type= 2 group by ORG_ID, JYEAR), CTE_DiffExchangeRateTax as (select  ORG_ID, (SUM(COALESCE(remain,0))/COALESCE(4 , 1)) * 0.09 as remain, JYEAR, 6 as type from cte_UnionRemainAccounts where type= 6 group by ORG_ID, JYEAR), CTE_DiffExchangeRateTaxSum as (select  ORG_ID, (SUM(COALESCE(remain,0))/COALESCE(4 , 1)) + (SUM(COALESCE(remain,0))/COALESCE(4 , 1) * 0.09) as remain, JYEAR, 7 as type from cte_UnionRemainAccounts where type= 5 group by ORG_ID, JYEAR), CTE_CompYearProfit  as (select  ORG_ID, (SUM(COALESCE(remain,0))/COALESCE(4 , 1)) + ((SUM(COALESCE(remain,0))/COALESCE(4 , 1)) * 0.09) as remain, JYEAR, 8 as type from cte_UnionRemainAccounts where type in(2,5) group by ORG_ID, JYEAR), cte_DecimalCount as (select ps.ORG_ID,ps.ID,ps.name,ps.DECIMAL_COUNT,ps.FEE_DECIMAL from PA_ORGANIZATIONS as po inner join PA_SYMBOLS as ps on po.BASE_CURRENCY = ps.id and po.ORG_ID = ps.ORG_ID), Cte_RemainAccounts as(SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_SurplusRevTangibleAccounts UNION All SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_DiffExchangeRateAccounts UNION All  SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_PureProfit UNION All SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_SurplusRevTangibleTax UNION All SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_SurplusRevTangibleTaxSum UNION All SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_DiffExchangeRateTax UNION All SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_DiffExchangeRateTaxSum UNION All SELECT  ORG_ID, remain , JYEAR, TYPE FROM CTE_CompYearProfit), Cte_RemainAccountsBaseDecimalCount as (select cra.ORG_ID,oi.NAME as OrgName,  COALESCE(cra.remain, 0)/POWER(10, COALESCE(cdc.DECIMAL_COUNT, 0)) as remain , cra.JYEAR, cra.type  from Cte_RemainAccounts cra left join cte_DecimalCount cdc on cra.ORG_ID = cdc.ORG_ID left join org_info oi on cra.ORG_ID = oi.ID) select JSON_ARRAYAGG(JSON_OBJECT( 'ORG_ID',ORG_ID,'OrgName',OrgName,'type',type,'JYEAR',JYEAR,'YEAR',IF(JYEAR =0,'',concat('سال',' ',JYEAR)), 'remain',remain, 'title',CASE COALESCE(type,0)  WHEN 1 THEN 'سود  خالص' WHEN 2 THEN 'مازاد تجدید ارزیابی دارایی های ثابت مشهود' WHEN 3 THEN 'مالیات بر درآمد اقلام فوق' WHEN 4 THEN 'مالیات مربوط به سایر اقلام سود و زیان جامع' WHEN 5 THEN '.........' WHEN 6 THEN 'مالیات بر درآمد اقلام فوق'  WHEN 7 THEN 'سایر اقلام سود و زیان جامع پس از کسر مالیات' WHEN 8 THEN 'سود جامع سال'  ELSE '--'  END)) as result from Cte_RemainAccountsBaseDecimalCount  where JYEAR>=0 order by JYEAR ASC,type;","params":[]}]]);
teamyar.write_result(context,Res)
end

ComprehensiveStatement()